import React from 'react';
import { motion } from 'framer-motion';
import { BadgeAlert } from 'lucide-react';

export default function ScamRadar({ rates }) {
  return (
    <div style={{ background: '#ffffff', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 15px rgba(0,0,0,0.04)', height: '100%' }}>
      <h3 style={{ margin: '0 0 16px', display: 'flex', alignItems: 'center', gap: '8px', color: '#1e293b' }}>
        <BadgeAlert size={18} color="#dc2626" />
        Scam Radar & Rate Cards
      </h3>
      <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
        {rates.map((r, i) => (
          <motion.div
            key={i}
            layout
            style={{ background: '#f8fafc', border: '1px solid #e2e8f0', borderLeft: '4px solid #dc2626', borderRadius: '8px', padding: '12px' }}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
              <strong style={{ color: '#334155', fontSize: '14px' }}>{r.service}</strong>
              <div style={{ fontWeight: 'bold', fontSize: '14px', color: '#16a34a' }}>
                {r.rate}
              </div>
            </div>
            <div style={{ fontSize: '11px', color: '#dc2626', marginTop: '6px', fontStyle: 'italic' }}>
              ⚠️ {r.warning}
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );
}
